async function getHot(key: string, load: () => Promise<string>) {
  const cached = await redis.get(key);
  if (cached) return cached;

  // only one caller rebuilds: SET ... NX EX acts as a lock that expires if we crash
  const gotLock = await redis.set(`lock:${key}`, "1", { NX: true, EX: 10 });
  if (gotLock) {
    const value = await load();
    const ttl = 300 + Math.floor(Math.random() * 60);   // jitter: keys don't expire together
    await redis.set(key, value, { EX: ttl });
    await redis.del(`lock:${key}`);
    return value;
  }
  // everyone else: serve a stale copy if we keep one, or wait briefly and retry
  return (await redis.get(`stale:${key}`)) ?? (await sleep(100), getHot(key, load));
}

