// Two transfers A->B and B->A can deadlock if each locks its source first.
// Fix: always lock accounts in the same order (lower id first).
async function transfer(from: number, to: number, amount: number) {
  const [first, second] = from < to ? [from, to] : [to, from];
  await db.tx(async (t) => {
    await t.query("SELECT 1 FROM accounts WHERE id = $1 FOR UPDATE", [first]);
    await t.query("SELECT 1 FROM accounts WHERE id = $1 FOR UPDATE", [second]);
    await t.query("UPDATE accounts SET balance = balance - $2 WHERE id = $1", [from, amount]);
    await t.query("UPDATE accounts SET balance = balance + $2 WHERE id = $1", [to, amount]);
  });
}
